function localCharts(){try{const v=JSON.parse(localStorage.getItem(STORAGE_KEY)||'[]');return Array.isArray(v)?v:[];}catch{return[];}}
const accountChartsKey=userId=>`${STORAGE_KEY}.user.${userId}`;
const deletedChartsKey=userId=>`${STORAGE_KEY}.deleted.${userId}`;
function storedArray(key){try{const value=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(value)?value:[];}catch{return[];}}
function deletedCharts(userId){return storedArray(deletedChartsKey(userId));}
let chartSyncQueue=Promise.resolve();
function queueChartSync(userId){
  chartSyncQueue=chartSyncQueue.catch(()=>{}).then(async()=>{
    if(account.user?.id!==userId)return;
    const remote=await fetchSavedKPCharts(userId);
    if(account.user?.id!==userId)return;
    const deleted=deletedCharts(userId);
    const local=storedArray(accountChartsKey(userId));
    const merged=mergeKPCharts(local,remote,deleted);
    if(JSON.stringify(merged)!==JSON.stringify(remote))await writeSavedKPCharts(userId,merged);
    if(account.user?.id!==userId)return;
    localStorage.setItem(accountChartsKey(userId),JSON.stringify(merged));
    state.saved=merged;
    if(state.screen==='saved')render();
  }).catch(error=>{
    if(account.user?.id===userId){account.notice=title('ဇာတာ Cloud Sync မအောင်မြင်သေးပါ။ ပြန်ဝင်သည့်အခါ ထပ်စမ်းပါမည်။','Chart cloud sync failed. It will retry on your next sign-in.');if(account.open)render();}
    console.warn('KP chart sync failed',error);
  });
  return chartSyncQueue;
}
function persistSavedCharts(){
  const userId=account.user?.id;
  localStorage.setItem(userId?accountChartsKey(userId):STORAGE_KEY,JSON.stringify(state.saved));
  if(userId)void queueChartSync(userId);
}
function restoreAccountCharts(userId){
  const accountLocal=storedArray(accountChartsKey(userId));
  const guest=localCharts();
  state.saved=mergeKPCharts(accountLocal,guest,deletedCharts(userId));
  localStorage.setItem(accountChartsKey(userId),JSON.stringify(state.saved));
  if(guest.length)localStorage.removeItem(STORAGE_KEY);
  void queueChartSync(userId);
}
