function questionScreen(){const query=state.questionSearch.trim().toLowerCase(),filtered=state.questions.filter(q=>!query||`${q.groupMm} ${q.groupEn} ${q.titleMm} ${q.titleEn}`.toLowerCase().includes(query)),groups=new Map();filtered.forEach(q=>{const group=title(q.groupMm,q.groupEn);groups.set(group,[...(groups.get(group)||[]),q]);});return`${appHeader(title('ဟူးရားမေးခွန်းများ','Horary Questions'))}<main class="list-screen"><div class="search-box">${icon('search')}<input id="question-search" value="${safe(state.questionSearch)}" placeholder="${title('မေးခွန်းကို ရိုက်ရှာပါ','Search questions')}"></div><p class="list-count">${title(`မေးခွန်း ${filtered.length} ခု`,`${filtered.length} questions`)}</p>${[...groups].map(([g,items])=>`<section class="question-group"><h2>${safe(g)}</h2>${items.map(item=>`<button class="question-row" data-question="${safe(item.titleMm)}"><span>${safe(title(item.titleMm,item.titleEn))}</span>${icon('chevron')}</button>`).join('')}</section>`).join('')||`<div class="empty-card">${title('ကိုက်ညီသောမေးခွန်း မတွေ့ပါ။','No matching question.')}</div>`}</main>`;}
