  document.querySelector('#account-form')?.addEventListener('submit',async event=>{event.preventDefault();if(account.busy)return;const data=new FormData(event.currentTarget),email=String(data.get('email')||'').trim(),password=String(data.get('password')||'');if(account.mode==='signup'&&password!==String(data.get('confirm')||'')){account.error=title('စကားဝှက်နှစ်ခု မတူပါ။','Passwords do not match.');render();return;}account.busy=true;account.error='';try{const result=account.mode==='signup'?await emailSignUp(email,password):await emailSignIn(email,password);account.user=result.session?.user||null;if(result.session){account.open=false;}else{account.notice=title('Email မှ အတည်ပြုလင့်ခ်ကို စစ်ဆေးပါ။','Check your email for the confirmation link.');}render();}catch(error){account.error=error.message||title('အကောင့်ဝင်၍မရပါ။','Authentication failed.');render();}finally{account.busy=false;}});
  document.querySelector('[data-back]')?.addEventListener('click',goBack);
