function readProfile(validate=true){const form=document.querySelector('#chart-form');if(!form)return state.draft;const d=Object.fromEntries(new FormData(form).entries()),[hour='0',min='0',sec='0']=String(d.time||'00:00:00').split(':');const p={...state.draft,name:state.mode==='horary'?questionTitle(state.selectedQuestion):String(d.name||'').trim(),question:state.mode==='horary'?state.selectedQuestion:'',day:d.day,month:d.month,year:d.year,hour,min,sec,lat:d.lat,lon:d.lon,tz:d.tz,ayanamsaIndex:Number(d.ayanamsaIndex),horaryNumber:d.horaryNumber||'1',horaryNumberSystem:Number(d.horaryNumberSystem)||249,isHorary:state.mode==='horary',isTSPHorary:d.isTSPHorary==='on'};if(validate&&!p.name)throw new Error(title('အမည်ထည့်ပါ။','Enter a name.'));return p;}
