async function refreshForeignTravelTiming(){
  const chart=state.result;if(!chart||chart.foreignTravelTiming||state.foreignTravelTimingBusy)return;
  const profiles=planetSignifications(chart);
  if(iosForeignTravelReading(chart,profiles,false).score<55)return;
  const request=(state.foreignTravelTimingRequest||0)+1;state.foreignTravelTimingRequest=request;state.foreignTravelTimingBusy=true;
  try{const timing=await iosForeignTravelTiming(chart,profiles);if(state.result===chart&&state.foreignTravelTimingRequest===request)chart.foreignTravelTiming=timing;}
  catch(error){if(state.result===chart&&state.foreignTravelTimingRequest===request)state.foreignTravelTimingError=errorLabel(error,state.english);}
  finally{if(state.result===chart&&state.foreignTravelTimingRequest===request){state.foreignTravelTimingBusy=false;if(state.screen==='readings'&&state.readingCategory==='foreignTravel')render();}}
}
async function refreshHoraryReading(){const chart=state.result;if(!chart?.profile.isHorary||state.horaryBusy)return;const q=state.questions.find(item=>item.titleMm===(chart.profile.question||chart.profile.name)||item.titleEn===(chart.profile.question||chart.profile.name));if(!q){state.horaryError=title('မေးခွန်းကို စာရင်းထဲတွင် မတွေ့ပါ။','Question not found in the catalog.');render();return;}const request=++state.horaryRequest;state.horaryBusy=true;state.horaryResult=null;state.horaryError='';render();try{const reading=await horaryReading(chart,q,state.english);if(chart===state.result&&request===state.horaryRequest)state.horaryResult=reading;}catch(error){if(chart===state.result&&request===state.horaryRequest)state.horaryError=errorLabel(error,state.english);}finally{if(chart===state.result&&request===state.horaryRequest){state.horaryBusy=false;if(state.screen==='readings')render();}}}
