function bindLocation(){const results=document.querySelector('#city-results'),input=document.querySelector('#city-search');let searchTimer;const redraw=()=>{if(results)results.innerHTML=cityResultsMarkup();document.querySelector('#city-clear').hidden=!state.cityQuery;};const load=async()=>{if(cities.length>FAVORITE_CITIES.length||state.cityLoading)return;state.cityLoading=true;state.cityError='';redraw();try{cities=await loadCityCatalog();}catch(error){state.cityError=errorLabel(error,state.english);}finally{state.cityLoading=false;if(state.screen==='location')redraw();}};results?.addEventListener('click',event=>{const button=event.target.closest('[data-city]');if(button){const city=cities[Number(button.dataset.city)];if(!city)return;state.draft={...state.draft,cityName:displayCity(city),lat:String(city.lat),lon:String(city.lon),tz:String(offsetForCity(city,state.draft)),timeZoneId:city.timeZoneId||''};state.cityQuery='';history.back();return;}if(event.target.closest('#retry-city'))void load();});input?.addEventListener('input',event=>{state.cityQuery=event.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(redraw,120);});document.querySelector('#city-clear')?.addEventListener('click',()=>{state.cityQuery='';input.value='';redraw();input.focus();});document.querySelector('#manual-city-form')?.addEventListener('submit',event=>{event.preventDefault();const form=event.currentTarget;if(!form.reportValidity())return;const data=Object.fromEntries(new FormData(form).entries());state.draft={...state.draft,cityName:data.cityName.trim(),lat:data.lat,lon:data.lon,tz:data.tz,timeZoneId:''};state.cityQuery='';history.back();});void load();}
